query.const:
query ($a: string!, $s: Date!, $u: Date!) { viewer { accounts(filter: { accountTag: $a }) {
  durable_objects: durableObjectsPeriodicGroups(limit: 1, filter: { date_geq: $s, date_leq: $u }) { sum { rowsRead rowsWritten duration } }
  durable_object_requests: durableObjectsInvocationsAdaptiveGroups(limit: 1, filter: { date_geq: $s, date_leq: $u }) { sum { requests } }
  durable_object_storage: durableObjectsStorageGroups(limit: 1, filter: { date_geq: $s, date_leq: $u }) { max { storedBytes } }
  workers: workersInvocationsAdaptive(limit: 1, filter: { date_geq: $s, date_leq: $u }) { sum { requests cpuTimeUs } }
  workers_ai: aiInferenceAdaptiveGroups(limit: 1, filter: { date_geq: $s, date_leq: $u }) { sum { totalNeurons } }
  r2_storage: r2StorageAdaptiveGroups(limit: 1, filter: { date_geq: $s, date_leq: $u }) { max { payloadSize metadataSize } }
  r2_operations: r2OperationsAdaptiveGroups(limit: 20, filter: { date_geq: $s, date_leq: $u }) { sum { requests } dimensions { actionType } }
  kv_operations: kvOperationsAdaptiveGroups(limit: 10, filter: { date_geq: $s, date_leq: $u }) { sum { requests } dimensions { actionType } }
} } }

query ($a: string!, $host: string!, $paths: [string!], $from: Time!, $mid: Time!, $to: Time!) { viewer { accounts(filter: { accountTag: $a }) {
  resets_now: durableObjectsInvocationsAdaptiveGroups(limit: 50, filter: { datetime_geq: $mid, datetime_lt: $to, status: "exceededMemory" }, orderBy: [sum_requests_DESC]) { sum { requests } dimensions { namespaceId objectId } }
  resets_before: durableObjectsInvocationsAdaptiveGroups(limit: 50, filter: { datetime_geq: $from, datetime_lt: $mid, status: "exceededMemory" }, orderBy: [sum_requests_DESC]) { sum { requests } dimensions { namespaceId objectId } }
  first_paint_now: rumPerformanceEventsAdaptiveGroups(limit: 1, filter: { datetime_geq: $mid, datetime_lt: $to, requestHost: $host, requestPath_in: $paths }) { count quantiles { firstPaintP50 firstPaintP75 } }
  first_paint_before: rumPerformanceEventsAdaptiveGroups(limit: 1, filter: { datetime_geq: $from, datetime_lt: $mid, requestHost: $host, requestPath_in: $paths }) { count quantiles { firstPaintP50 firstPaintP75 } }
} } }

query ($a: string!, $s: Date!, $u: Date!) { viewer { accounts(filter: { accountTag: $a }) {
  durable_objects_written: durableObjectsPeriodicGroups(limit: 1000, filter: { date_geq: $s, date_leq: $u }, orderBy: [sum_rowsWritten_DESC]) { sum { rowsRead rowsWritten } dimensions { datetimeHour objectId } }
  durable_objects_read: durableObjectsPeriodicGroups(limit: 1000, filter: { date_geq: $s, date_leq: $u }, orderBy: [sum_rowsRead_DESC]) { sum { rowsRead rowsWritten } dimensions { datetimeHour objectId } }
  workers: workersInvocationsAdaptive(limit: 1000, filter: { date_geq: $s, date_leq: $u }, orderBy: [sum_requests_DESC]) { sum { requests cpuTimeUs } dimensions { datetimeHour scriptName } }
} } }
